/**
 * prompt-input — AI prompt-field demo, centered.
 *
 * A small pill with an AI-sparkles icon springs in, expands horizontally
 * into a full-width prompt bar, then types out a sample prompt character
 * by character. Use to showcase HOW a user prompts the product — the
 * prompt UX itself becomes the focal element. Pairs with any modern
 * "ask the AI" / "describe what you want" / "type your prompt" affordance.
 *
 * Centered on a solid background (or media if the user sets one). No
 * other text — the prompt form is the entire scene.
 */

import * as React from "react";
import type { VariableField } from "../video-config";
import type { SceneTemplateProps } from "./types";
import {
  SceneBackground,
  mediaBackgroundSchemaFields,
  mediaBackgroundDefaults,
} from "./scene-background";
import { stripPipe } from "../typography";
import { PromptInputPill } from "../primitives/typography/PromptInputPill";

export const promptInputSchema: Record<string, VariableField> = {
  promptText: {
    type: "string",
    label: "Prompt text",
    default: "Make a launch video for our app",
    required: true,
    description:
      "Example prompt that types into the AI prompt bar. 3-7 words / ~25-40 characters reads best. Longer prompts auto-shrink the font-size to fit the pill width, but stay most legible at the natural size. Demonstrates the product's prompt UX (e.g. 'Make a launch video for our app', 'Generate a customer testimonial', 'Build a 6-second product showcase').",
  },
  pillBg: {
    type: "color",
    label: "Pill background",
    default: "",
    description: "Prompt-pill background color. Leave empty for white.",
  },
  pillTextColor: {
    type: "color",
    label: "Pill text color",
    default: "",
    description: "Color of the prompt text. Leave empty for slate-grey (#374151, the AI-prompt-UI standard) — feels more considered than raw black.",
  },
  ...mediaBackgroundSchemaFields,
};

export const promptInputDefaults: Record<string, unknown> = {
  promptText: "Make a launch video for our app",
  pillBg: "",
  pillTextColor: "",
  ...mediaBackgroundDefaults,
};

export const PromptInputTemplate: React.FC<SceneTemplateProps> = ({
  variables,
  style,
  progress,
  beatIntensity,
  width,
  height,
  sceneDuration,
  isPlaying = true,
  backgroundEffect,
}) => {
  const font = `${style.font ? `${style.font}, ` : ""}Inter, -apple-system, 'SF Pro Text', system-ui, 'Segoe UI', Roboto, sans-serif`;

  const promptText = stripPipe(String(variables.promptText || "Make a launch video for our app"));
  const pillBg = String(variables.pillBg || "").trim() || "#FFFFFF";
  const pillTextColor = String(variables.pillTextColor || "").trim() || "#374151";
  const seed = promptText.split("").reduce((acc, c) => acc + c.charCodeAt(0), 0);

  return (
    <div
      style={{
        width,
        height,
        position: "relative",
        overflow: "hidden",
        backgroundColor: "#000",
        fontFamily: font,
      }}
    >
      {/* [slot: background] Gradient / media backdrop */}
      <SceneBackground
        style={style}
        progress={progress}
        sceneDuration={sceneDuration}
        width={width}
        height={height}
        mediaUrl={String(variables.mediaUrl || "")}
        mediaType={String(variables.mediaType || "auto")}
        mediaPoster={String(variables.mediaPoster || "")}
        backgroundEffect={backgroundEffect}
        seed={seed}
        isPlaying={isPlaying}
        beatIntensity={beatIntensity}
      />

      {/* [slot: hero] Centered pill — PromptInputPill primitive (typed
          prompt is the content; no separate caption slot) */}
      <PromptInputPill
        progress={progress}
        sceneDuration={sceneDuration ?? 4}
        promptText={promptText}
        pillBg={pillBg}
        pillTextColor={pillTextColor}
        width={width}
        height={height}
      />
    </div>
  );
};

/**
 * PromptInputPill
 *
 * AI prompt-bar focal element: pill scales in as a small circle (icon only),
 * expands horizontally to full width, then typewrites a sample prompt
 * character-by-character. Sparkles icon on the left, blinking cursor at the
 * end of the typed text.
 *
 * prompt-input.tsx is refactored to consume this component so both paths
 * render byte-identical DOM. Snapshot test in __tests__/prompt-input-
 * extraction.test.tsx verifies pixel-identity at 5 progress timestamps.
 *
 * Two surfaces:
 *   1. <PromptInputPill {...typedProps} /> — direct use from templates
 *   2. Registered primitive — used by custom scenes via composition JSON
 */

import * as React from "react";
import { interpolate, spring, SPRING_BOUNCY, SPRING_SMOOTH } from "../../motion";
import { stripPipe } from "../../typography";

const CLAMP = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

// ─── Sparkles icon (lifted verbatim from prompt-input) ───────────

const SparklesIcon: React.FC<{ size: number; gradientId: string }> = ({ size, gradientId }) => (
  <svg width={size} height={size} viewBox="0 0 16 16" fill="none">
    <defs>
      <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#7C3AED" />
        <stop offset="50%" stopColor="#3B82F6" />
        <stop offset="100%" stopColor="#06B6D4" />
      </linearGradient>
    </defs>
    <path
      d="M7.657 6.247c.11-.33.576-.33.686 0l.645 1.937a2.89 2.89 0 0 0 1.829 1.828l1.936.645c.33.11.33.576 0 .686l-1.937.645a2.89 2.89 0 0 0-1.828 1.829l-.645 1.936a.361.361 0 0 1-.686 0l-.645-1.937a2.89 2.89 0 0 0-1.828-1.828l-1.937-.645a.361.361 0 0 1 0-.686l1.937-.645a2.89 2.89 0 0 0 1.828-1.828zM3.794 1.148a.217.217 0 0 1 .412 0l.387 1.162c.173.518.579.924 1.097 1.097l1.162.387a.217.217 0 0 1 0 .412l-1.162.387A1.73 1.73 0 0 0 4.593 5.69l-.387 1.162a.217.217 0 0 1-.412 0L3.407 5.69A1.73 1.73 0 0 0 2.31 4.593l-1.162-.387a.217.217 0 0 1 0-.412l1.162-.387A1.73 1.73 0 0 0 3.407 2.31zM10.863.099a.145.145 0 0 1 .274 0l.258.774c.115.346.386.617.732.732l.774.258a.145.145 0 0 1 0 .274l-.774.258a1.16 1.16 0 0 0-.732.732l-.258.774a.145.145 0 0 1-.274 0l-.258-.774a1.16 1.16 0 0 0-.732-.732L9.1 2.137a.145.145 0 0 1 0-.274l.774-.258c.346-.115.617-.386.732-.732z"
      fill={`url(#${gradientId})`}
    />
  </svg>
);

// ─── Typed component (direct use from templates) ────────────────

export interface PromptInputPillProps {
  progress: number;
  sceneDuration: number;
  /** Prompt text typed into the pill */
  promptText: string;
  /** Pill background color (default #FFFFFF) */
  pillBg?: string;
  /** Color of the typed text (default #374151 — Tailwind gray-700) */
  pillTextColor?: string;
  /** Frame width */
  width: number;
  /** Frame height */
  height: number;
}

export const PromptInputPill: React.FC<PromptInputPillProps> = ({
  progress,
  sceneDuration,
  promptText: rawText,
  pillBg = "#FFFFFF",
  pillTextColor = "#374151",
  width,
  height,
}) => {
  const dim = Math.min(width, height);
  const promptText = stripPipe(rawText || "");
  const seed = promptText.split("").reduce((acc, c) => acc + c.charCodeAt(0), 0);

  // Sizing — verbatim from prompt-input
  const pillHeight = dim * 0.13;
  const pillTargetWidth = Math.min(width * 0.86, dim * 0.95);
  const pillCircleWidth = pillHeight;
  const pillRadius = pillHeight / 2;
  const iconSize = pillHeight * 0.46;
  const padLeft = pillHeight * 0.30;
  const fontSizeDefault = pillHeight * 0.42;
  const availableTextWidth = pillTargetWidth - padLeft * 3 - iconSize;
  const naturalTextWidth = promptText.length * fontSizeDefault * 0.55 * 1.06;
  // Allow shrink down to 0.45× — the prior 0.6 floor wasn't aggressive
  // enough for unexpectedly long prompts and left them hard-clipped at
  // the right edge of the pill (stress test caught a 130-char prompt
  // overflowing). 0.45 keeps text readable even after shrink. The pill
  // body has overflow: hidden so anything that still doesn't fit clips
  // cleanly instead of running past the pill border.
  const shrinkFactor =
    naturalTextWidth > availableTextWidth
      ? Math.max(0.45, availableTextWidth / naturalTextWidth)
      : 1;
  const fontSize = fontSizeDefault * shrinkFactor;

  // Reveal sequence — verbatim from prompt-input
  const enterSpring = spring(
    interpolate(progress, [0, 0.10], [0, 1], CLAMP),
    SPRING_BOUNCY,
  );
  const enterScale = 0.7 + 0.3 * enterSpring;
  const enterOpacity = interpolate(progress, [0, 0.08], [0, 1], CLAMP);

  const widthProgress = spring(
    interpolate(progress, [0.10, 0.30], [0, 1], CLAMP),
    SPRING_SMOOTH,
  );
  const pillWidth = pillCircleWidth + (pillTargetWidth - pillCircleWidth) * widthProgress;

  const typeStart = 0.30;
  const typeEnd = 0.68;
  const charsRevealed = Math.max(
    0,
    Math.floor(
      interpolate(progress, [typeStart, typeEnd], [0, promptText.length], CLAMP),
    ),
  );
  const visibleText = promptText.slice(0, charsRevealed);

  const realT = progress * sceneDuration;
  const cursorVisible =
    progress >= typeStart * 0.9 && Math.sin(realT * Math.PI * 2.4) > 0;

  return (
    <div
      style={{
        position: "absolute",
        top: "50%",
        left: "50%",
        transform: `translate(-50%, -50%) scale(${enterScale})`,
        opacity: enterOpacity,
      }}
    >
      <div
        style={{
          width: pillWidth,
          height: pillHeight,
          backgroundColor: pillBg,
          borderRadius: pillRadius,
          display: "flex",
          alignItems: "center",
          paddingLeft: padLeft,
          paddingRight: padLeft,
          // Clip at the pill border — even after the 0.45× shrink floor,
          // pathologically long prompts can still exceed the pill width.
          // Clipping at the rounded border looks cleaner than letting text
          // bleed past the right edge.
          overflow: "hidden",
          boxShadow: [
            `inset 0 ${1 * (dim / 1080)}px 0 rgba(255,255,255,0.85)`,
            `0 ${8 * (dim / 1080)}px ${24 * (dim / 1080)}px ${-8 * (dim / 1080)}px rgba(110,80,200,0.10)`,
            `0 ${2 * (dim / 1080)}px ${8 * (dim / 1080)}px ${-4 * (dim / 1080)}px rgba(0,0,0,0.05)`,
          ].join(", "),
          whiteSpace: "nowrap",
        }}
      >
        <div
          style={{
            flexShrink: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            width: iconSize,
            height: iconSize,
          }}
        >
          <SparklesIcon size={iconSize} gradientId={`prompt-input-grad-${seed}`} />
        </div>
        <div
          style={{
            marginLeft: padLeft,
            fontSize,
            lineHeight: 1.4,
            color: pillTextColor,
            fontWeight: 500,
            letterSpacing: -0.5,
            minWidth: 0,
            display: "flex",
            alignItems: "center",
          }}
        >
          <span>{visibleText}</span>
          <span
            style={{
              display: "inline-block",
              width: fontSize * 0.06,
              height: fontSize * 0.95,
              backgroundColor: pillTextColor,
              marginLeft: fontSize * 0.08,
              opacity: cursorVisible ? 0.85 : 0,
              borderRadius: fontSize * 0.03,
            }}
          />
        </div>
      </div>
    </div>
  );
};

/**
 * SceneBackground — shared backdrop component for any scene template that
 * wants to support both a brand-color gradient and stock media (Pexels
 * photo / video) as an alternate atmosphere.
 *
 * Usage:
 *   <SceneBackground
 *     style={style}
 *     progress={progress}
 *     sceneDuration={sceneDuration}
 *     width={width}
 *     height={height}
 *     mediaUrl={String(variables.mediaUrl || "")}
 *     mediaType={String(variables.mediaType || "auto")}
 *     seed={String(variables.texts || "")}
 *     isPlaying={isPlaying}
 *   />
 *   ... template's content layered on top
 *
 * Behavior:
 *   - Brand gradient is the always-on backdrop (uses BrandGradientOverlay).
 *   - When mediaUrl is set and mediaType isn't "gradient", the photo/video
 *     covers the gradient. Vignette + bottom-half darken give the content
 *     contrast against busy footage.
 *   - mediaType="gradient" deliberately ignores mediaUrl and renders only
 *     the brand gradient. First-class atmospheric mode.
 *   - When mediaUrl is empty / 404s / Pexels search returned nothing,
 *     gradient shows through cleanly (matches every other gradient-backed
 *     template).
 *
 * Extracted from bg-media.tsx so any template can compose it. bg-media
 * now uses this component too — its "media is the scene" identity comes
 * from how it positions the title (centered, full-frame), not from
 * duplicated render logic.
 */

import React, { useEffect, useRef } from "react";
import type { GlobalStyle, VariableField } from "../video-config";
import { BrandGradientOverlay } from "../backgrounds";
import { getBackgroundTransform } from "../backgrounds";

const VIDEO_EXTENSIONS = [".mp4", ".webm", ".mov", ".m4v", ".avi"];

function isVideoUrl(url: string): boolean {
  try {
    const pathname = new URL(url).pathname.toLowerCase();
    return VIDEO_EXTENSIONS.some((ext) => pathname.endsWith(ext));
  } catch {
    const lower = url.toLowerCase();
    return VIDEO_EXTENSIONS.some((ext) => lower.endsWith(ext));
  }
}

export type ResolvedMediaType = "photo" | "video" | "gradient";

export function resolveMediaType(
  mediaType: string,
  mediaUrl: string,
): ResolvedMediaType {
  if (mediaType === "gradient") return "gradient";
  if (mediaType === "video") return "video";
  if (mediaType === "photo") return "photo";
  // "auto" — detect from URL extension
  return mediaUrl && isVideoUrl(mediaUrl) ? "video" : "photo";
}

/**
 * Standard schema fields any template can spread into its variableSchema
 * to enable media backgrounds. Keeps the field set + descriptions
 * consistent across templates.
 */
export const mediaBackgroundSchemaFields: Record<string, VariableField> = {
  mediaUrl: {
    type: "media",
    label: "Background media",
    description: "Optional photo or video URL behind this scene. When set, replaces the brand gradient.",
  },
  mediaKeyword: {
    type: "string",
    label: "Background search keyword",
    default: "",
    description: "2-4 word English term for Pexels stock-footage search (auto-fills mediaUrl).",
  },
  mediaType: {
    type: "enum",
    label: "Background media type",
    default: "auto",
    description: "auto detects photo/video from URL. 'gradient' is a deliberate mode — atmospheric brand-color scene with no stock footage.",
    options: ["auto", "photo", "video", "gradient"],
  },
  mediaPoster: {
    type: "string",
    label: "Background poster image",
    default: "",
    description: "Still image URL shown while a video backdrop is decoding its first frame. Auto-filled from Pexels' thumbnail when fillPexelsUrls sets a video mediaUrl. Hides the gradient flash that would otherwise appear in the ~50–400ms gap between a <video> mounting and decoding its first frame.",
  },
};

/** Default values for the media-background fields. Spread into a template's defaults. */
export const mediaBackgroundDefaults: Record<string, unknown> = {
  mediaUrl: "",
  mediaKeyword: "",
  mediaType: "auto",
  mediaPoster: "",
};

export interface SceneBackgroundProps {
  style: GlobalStyle;
  progress: number;
  sceneDuration?: number;
  width: number;
  height: number;
  mediaUrl?: string;
  mediaType?: string;
  /** Still image URL shown while the <video> backdrop decodes its first
   *  frame. Without it the element renders transparent during the
   *  ~50–400ms decode window and the gradient flashes through. */
  mediaPoster?: string;
  /** Background motion effect (drift / pulse / Ken Burns). Applied to the photo/video. */
  backgroundEffect?: string;
  /** Stable seed for the gradient breathing animation. Pass the scene's
   *  text content (or any stable string) — it's hashed deterministically. */
  seed?: number | string;
  /** Pause video when preview is paused. Defaults to true (export path). */
  isPlaying?: boolean;
  beatIntensity?: number;
}

export const SceneBackground: React.FC<SceneBackgroundProps> = ({
  style,
  progress,
  sceneDuration,
  width: _width,  // accepted for symmetry; not currently used in render
  height,
  mediaUrl = "",
  mediaType = "auto",
  mediaPoster,
  backgroundEffect,
  seed,
  isPlaying = true,
  beatIntensity = 0,
}) => {
  void _width;
  const resolved = resolveMediaType(mediaType, mediaUrl);
  const showMedia = resolved !== "gradient" && !!mediaUrl;

  const gradSeed = typeof seed === "number"
    ? seed
    : typeof seed === "string"
      ? seed.split("").reduce((acc, c) => acc + c.charCodeAt(0), 0)
      : 0;

  const bgTransform = getBackgroundTransform(backgroundEffect, progress, beatIntensity);

  // Video playback control — same pause/seek logic bg-media used pre-extract.
  const videoRef = useRef<HTMLVideoElement>(null);
  const lastProgress = useRef(progress);
  const videoStarted = useRef(false);

  useEffect(() => {
    const vid = videoRef.current;
    if (!vid) return;
    if (!isPlaying) {
      vid.pause();
      videoStarted.current = false;
      return;
    }
    const progressChanged = Math.abs(progress - lastProgress.current) > 0.001;
    lastProgress.current = progress;
    if (progressChanged && !videoStarted.current) {
      vid.playbackRate = 1;
      vid.currentTime = 0;
      vid.play().catch(() => {});
      videoStarted.current = true;
    } else if (!progressChanged && videoStarted.current) {
      vid.pause();
      videoStarted.current = false;
    }
  }, [progress, isPlaying]);

  // Release the decoder on unmount. Without this, iOS Safari keeps the
  // video's decoder buffer alive after the React node is gone — each
  // scene transition (or play/pause/play cycle that remounts the active
  // scene) leaks one decoder, eventually crossing the renderer's memory
  // ceiling and triggering "A problem repeatedly occurred." Same recipe
  // as #409's CanvasPreview preload cleanup: pause → clear src → load().
  // Capture the ref at mount-time so the cleanup uses the same node we
  // mounted (the ref's .current is stale by unmount).
  useEffect(() => {
    const vid = videoRef.current;
    return () => {
      if (!vid) return;
      vid.pause();
      vid.removeAttribute("src");
      vid.load();
    };
  }, []);

  return (
    <>
      <BrandGradientOverlay
        style={style}
        progress={progress}
        sceneDuration={sceneDuration}
        seed={gradSeed}
      />

      {showMedia && (resolved === "video" ? (
        <video
          ref={videoRef}
          src={mediaUrl}
          // Poster paints during the decode window so the user sees the
          // (still) first frame instead of a transparent <video> letting
          // the brand gradient show through. Pexels returns a thumbnail
          // image alongside each video; fillPexelsUrls stores it in
          // `variables.mediaPoster`. Layered defense alongside preload="auto"
          // below: on desktop the byte preloader makes decode fast, on
          // mobile (where the preloader skips video pre-mounting to dodge
          // the iOS Safari memory crash) the poster is the primary shield.
          poster={mediaPoster || undefined}
          muted
          loop
          playsInline
          // preload="auto" — without it, browsers default to "metadata":
          // they only load the container/dimensions, not the byte stream
          // needed to decode frames. The element then renders transparent
          // until the first decoded frame arrives, letting the brand
          // gradient flash through whenever a scene mid-playback transitions
          // to a media backdrop. The parent preloader caches the bytes, but
          // decoder state is per-element, so the active mount still has to
          // decode the first frame; "auto" kicks that work off the instant
          // the element mounts.
          preload="auto"
          style={{
            position: "absolute",
            inset: 0,
            width: "100%",
            height: "100%",
            objectFit: "cover",
            transform: bgTransform.transform,
            transformOrigin: bgTransform.transformOrigin,
          }}
        />
      ) : (
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: bgTransform.transform,
            transformOrigin: bgTransform.transformOrigin,
            backgroundImage: `url(${mediaUrl})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
          }}
        />
      ))}

      {showMedia && (
        <>
          {/* Vignette — gives the content contrast against busy footage. */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                "radial-gradient(ellipse at center, transparent 30%, rgba(0,0,0,0.55) 80%, rgba(0,0,0,0.75) 100%)",
              pointerEvents: "none",
            }}
          />
          {/* Center-text scrim — soft elliptical darken where headlines /
              wordStagger words / metrics typically land. Subtle (max ~22%
              darken at the focal point) so the photo still reads bright at
              the edges, but text on busy bg gets reliable contrast without
              relying on heavier shadows. */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background:
                "radial-gradient(ellipse 85% 50% at 50% 50%, rgba(0,0,0,0.22) 0%, rgba(0,0,0,0.10) 50%, transparent 80%)",
              pointerEvents: "none",
            }}
          />
          {/* Bottom-half darken — improves text readability on photos. */}
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              bottom: 0,
              height: height * 0.45,
              background:
                "linear-gradient(to top, rgba(0,0,0,0.5) 0%, transparent 100%)",
              pointerEvents: "none",
            }}
          />
        </>
      )}
    </>
  );
};

/**
 * Scene template types.
 *
 * A template is a reusable React component that defines how a scene looks.
 * It declares what variables it needs (auto-shown as input fields in the Studio)
 * and receives universal settings as props.
 *
 * Templates are searchable by AI via description, category, jobs, register,
 * and useWhen guidance.
 * The variable schema enables any LLM to fill in template variables via JSON.
 */

import type { ResolvedTokens } from "../theme";
import type { GlobalStyle, VariableField, SafeZone } from "../video-config";

/**
 * Props passed to every scene template component.
 *
 * All animation must be driven by `progress` (0→1). No CSS animations,
 * no Framer Motion, no requestAnimationFrame. Use interpolate/spring
 * from animation-utils.ts.
 *
 * Scale factor: use `Math.min(width, height) / 1080` — normalizes to
 * the short edge so visuals are consistent across portrait and landscape.
 */
export interface SceneTemplateProps {
  variables: Record<string, unknown>;
  style: GlobalStyle;
  /** 0→1 through the scene's duration */
  progress: number;
  /** 0→1 beat pulse intensity */
  beatIntensity: number;
  /** 1080 (portrait) or 1920 (landscape) */
  width: number;
  /** 1920 (portrait) or 1080 (landscape) */
  height: number;
  /** Video-level default text effect (for templates that opt in via usesGlobalTextEffect) */
  textArchetype?: string;
  /** How text leaves the scene (fade / shrink / pop / blur-scale). Falls back to a sensible default per textArchetype when undefined. */
  /** Video-level default background effect (for templates that opt in via usesGlobalBackgroundEffect) */
  backgroundEffect?: string;
  /** Platform-aware safe zone insets in pixels — use for text placement */
  safeZone: SafeZone;
  /** Scene duration in seconds — use for time-based (not progress-based) animations */
  sceneDuration?: number;
  /**
   * Brand tokens already resolved from `style`. Built-in templates import
   * resolveTokens directly; an ejected `custom_*` scene can't import anything,
   * so without this it has no way to reach the same values and ends up
   * hardcoding white, black and shadows — the body then looks generic next to
   * a frame that IS using the brand.
   */
  tokens?: ResolvedTokens;
  /**
   * True when the preview player is actively advancing progress; false when paused.
   * Templates that play HTML5 <video> elements should pause them when this is false.
   * Undefined (export capture path) is treated as true.
   */
  isPlaying?: boolean;
}

/**
 * What a template can DO inside a video. A template can serve more than
 * one job — `bigNumber` is `["claim", "proof"]`; `media` is
 * `["atmosphere", "setup"]`. Used by the chat composer to pick templates
 * by scene-job rather than by the (less useful) category bucket.
 *
 * - `setup` — opens the world, names the subject, frames the question
 * - `claim` — makes a falsifiable statement the rest of the video earns
 * - `proof` — backs a claim with a number, quote, mockup, code, or chart
 * - `atmosphere` — breathing room; ties scenes together visually
 * - `payoff` — punchline, reveal, or satisfying answer to an earlier setup
 * - `punctuation` — short energy beat that breaks pattern or lands a joke
 * - `ask` — pushes the viewer to the next action; closer-territory only
 */
export type TemplateJob = "setup" | "claim" | "proof" | "atmosphere" | "payoff" | "punctuation" | "ask";

/**
 * The visual register a template lives in — what the *viewer* notices
 * before reading any copy. The chat's diversity rule reads this rather
 * than `category` because two `card-led` bodies look the same to the
 * viewer even when they're a `testimonial` and a `bigNumber`.
 *
 * - `motion-led` — animation IS the content (confetti, emoji rain, charts)
 * - `typography-led` — text fills the frame (bigNumber, ctaLogo, tripleStats)
 * - `device-led` — phone/browser/terminal frame is the focal element
 * - `card-led` — quote/feature/comparison cards
 * - `mockup-led` — full UI surface (chat thread, search results, app feed)
 */
export type TemplateRegister =
  | "motion-led"
  | "typography-led"
  | "device-led"
  | "card-led"
  | "mockup-led";

/**
 * A registered scene template.
 */
export interface SceneTemplate {
  id: string;
  /** Built-in templates leave these blank — DB owns them. Vibecoded
   *  templates carry their own here since they have no DB row. */
  label?: string;
  description?: string;
  category?: string | null;
  /** What this template DOES inside a video. 1-3 jobs. See TemplateJob. */
  jobs?: TemplateJob[];
  /** The visual register the template lives in. See TemplateRegister. */
  register?: TemplateRegister;
  /** Semantic selection guidance: when this template is the right choice. */
  useWhen?: string;
  /** Thumbnail URL for visual picker (optional) */
  thumbnail?: string;
  /** If true, template consumes the video-level defaultTextArchetype */
  usesGlobalTextEffect: boolean;
  /** If true, template uses the video-level defaultTransition */
  usesGlobalTransition: boolean;
  /** If true, template uses the video-level defaultBackgroundEffect */
  usesGlobalBackgroundEffect: boolean;
  /**
   * Spatial budget for text effects.
   * - "tight" (default): text shares the frame with UI (mockup, chart). Expressive
   *   effects are auto-clamped to contained equivalents to prevent clipping.
   * - "open": text is the focal element (bg-* templates). All effects allowed.
   */
  textCanvas?: "tight" | "open";
  /**
   * Hard input gates — what this template needs from the user's input to fire
   * legitimately. The AI uses these to filter out templates that would force
   * it to invent content (e.g. \`bigNumber\` without a real number).
   *
   * Set to true when the template's value depends on input that the model
   * can't fabricate honestly: a stat, a quote, an uploaded screenshot.
   * Defaults to false (no constraint).
   */
  requiresStat?: boolean;
  requiresQuote?: boolean;
  requiresScreenshot?: boolean;
  /** Template can be backed by Pexels stock footage (e.g. \`media\`). */
  allowsStockMedia?: boolean;
  /** Variable schema — Studio auto-generates inputs from this */
  variableSchema: Record<string, VariableField>;
  /** Default values for all variables */
  defaultVariables: Record<string, unknown>;
  /** Minimum scene duration in seconds */
  minDuration?: number;
  /** Recommended scene duration in seconds */
  preferredDuration?: number;
  /** The React component that renders this template */
  component: React.FC<SceneTemplateProps>;
}

/**
 * Serializable template metadata (no component) — for edge functions, API, MCP.
 */
export interface SceneTemplateMetadata {
  id: string;
  usesGlobalTextEffect: boolean;
  usesGlobalTransition: boolean;
  usesGlobalBackgroundEffect: boolean;
  textCanvas?: "tight" | "open";
  /** Hard input gates — see SceneTemplate.requiresStat etc. */
  requiresStat?: boolean;
  requiresQuote?: boolean;
  requiresScreenshot?: boolean;
  allowsStockMedia?: boolean;
  /** What this template DOES inside a video. 1-3 jobs. See TemplateJob. */
  jobs?: TemplateJob[];
  /** The visual register the template lives in. See TemplateRegister. */
  register?: TemplateRegister;
  /** Semantic selection guidance: when this template is the right choice. */
  useWhen?: string;
  variableSchema: Record<string, VariableField>;
  defaultVariables: Record<string, unknown>;
  minDuration?: number;
  preferredDuration?: number;
}
